$model->saveTemplate(['key'=>'list_page','label'=>'List page','renderer'=>'standard','fields'=>['amount','note']]);$created=[];
for($i=0;$i<61;$i++)$created[]=$pages->save(['title'=>'Original '.str_pad((string)$i,3,'0',STR_PAD_LEFT),'slug'=>'list-'.str_pad((string)$i,3,'0',STR_PAD_LEFT),'template'=>'list_page','body'=>'Large original '.str_repeat('Originalinhalt ',5000),'custom_fields'=>['amount'=>$i.'.123456','note'=>$i%2===0?'literal 100%_ Ähre':'other']],0);
