$filter=['columns'=>['title','custom.amount'],'selectors'=>[['any'=>[['field'=>'custom.note','op'=>'contains_ci','value'=>'100%_ ähre'],['field'=>'title','op'=>'eq','value'=>'Original 001']]]],'order'=>[['field'=>'custom.amount','direction'=>'desc']]];
