$panel=new ContentListPanel($db,$access,'own-csrf');$markup=$panel->render(['list_id'=>$saved['id']]);$dom=new DOMDocument();@$dom->loadHTML('<?xml encoding="UTF-8">'.$markup);$xpath=new DOMXPath($dom);
listCheck($xpath->query('//*[@data-content-list-row]')->length===10&&$xpath->query('//details[@data-filter-expression and not(@open)]')->length===1,'real editor renders ten results and closed configuration controls');
listCheck(!str_contains($markup,'Large original'),'list view contains chosen projections only');
listReject(fn()=>$panel->action(['operation'=>'content-list-save','csrf'=>'wrong','list_config'=>'{}']),'real controller rejects stale CSRF without modifying originals');
listReject(fn()=>$panel->action(['operation'=>'content-list-batch','csrf'=>'own-csrf','list_config'=>json_encode($config),'selected'=>[$created[0]['id'].':1']]),'bulk query needs explicit original-selection confirmation');
listReject(fn()=>(new ContentLists($db,new Access($db,$actors['reader'])))->batch($config,[$created[0]['id'].':1']),'read-only user cannot prepare a business mutation');
