listReject(fn()=>$lists->batch($config,[$created[0]['id'].':1',$created[0]['id'].':1']),'duplicate original selection is rejected');
listReject(fn()=>$lists->batch($filter,[$created[3]['id'].':1']),'changed or unmatched originals cannot enter a reviewed filter batch');
$lists->save($saved['id'],2,'Aktuelle Beträge',$filter,true);listCheck($lists->presets()===[],'removed preset disappears without removing its original revision history');listReject(fn()=>$lists->get($saved['id']),'removed private preset cannot be accidentally reopened');
listCheck(ownOriginalDatabaseHash($db,$tables)===$before,'all source page, revision, publication and media bytes stay exact');
